import{_ as d,o as a,c as e,ag as n}from"./chunks/framework.BwE_uGt8.js";const b=JSON.parse('{"title":"SDK 概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/sdk.md","filePath":"zh/guide/sdk.md"}'),o={name:"zh/guide/sdk.md"};function s(r,t,l,c,i,h){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="sdk-概览" tabindex="-1">SDK 概览 <a class="header-anchor" href="#sdk-概览" aria-label="Permalink to &quot;SDK 概览&quot;">​</a></h1><p>Talon 提供 <strong>5 种语言</strong> 的官方 SDK，全部实现 10 个引擎模块的 100% API 覆盖。</p><p>所有 SDK 通过统一的 <code>talon_execute</code> C ABI 与 Talon 引擎通信 — 相同的 JSON 命令协议，跨语言行为一致。</p><h2 id="支持语言" tabindex="-1">支持语言 <a class="header-anchor" href="#支持语言" aria-label="Permalink to &quot;支持语言&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>安装方式</th><th>绑定方式</th><th>Native Lib</th></tr></thead><tbody><tr><td><a href="/talon-docs/zh/guide/sdk-go.html">Go</a></td><td><code>go get</code></td><td>cgo（静态链接）</td><td>编译进二进制</td></tr><tr><td><a href="/talon-docs/zh/guide/sdk-python.html">Python</a></td><td><code>pip install talon-db</code></td><td>ctypes</td><td>首次使用时自动下载</td></tr><tr><td><a href="/talon-docs/zh/guide/sdk-nodejs.html">Node.js</a></td><td><code>npm install talon-db</code></td><td>ffi-napi</td><td>安装时自动下载</td></tr><tr><td><a href="/talon-docs/zh/guide/sdk-java.html">Java</a></td><td>源码构建</td><td>JNA</td><td>从 <code>lib/</code> 目录加载</td></tr><tr><td><a href="/talon-docs/zh/guide/sdk-dotnet.html">.NET</a></td><td><code>dotnet add package TalonDb</code></td><td>P/Invoke</td><td>NuGet 包内置</td></tr></tbody></table><h2 id="模块覆盖" tabindex="-1">模块覆盖 <a class="header-anchor" href="#模块覆盖" aria-label="Permalink to &quot;模块覆盖&quot;">​</a></h2><p>全部 SDK 覆盖完整的 10 个引擎模块：</p><table tabindex="0"><thead><tr><th>模块</th><th>方法数</th><th>说明</th></tr></thead><tbody><tr><td>SQL</td><td>1</td><td>关系型查询</td></tr><tr><td>KV</td><td>17</td><td>键值存储（TTL / 原子操作 / 分页扫描）</td></tr><tr><td>Vector</td><td>7</td><td>HNSW 向量索引与搜索</td></tr><tr><td>TS</td><td>7</td><td>时序引擎</td></tr><tr><td>MQ</td><td>9</td><td>消息队列</td></tr><tr><td>AI</td><td>19</td><td>Session / Context / Memory / Trace</td></tr><tr><td>FTS</td><td>16</td><td>全文搜索（BM25 + 模糊 + 混合搜索）</td></tr><tr><td>Geo</td><td>10</td><td>地理空间（半径 / 矩形 / 围栏）</td></tr><tr><td>Graph</td><td>19</td><td>属性图（CRUD + BFS + 最短路径 + PageRank）</td></tr><tr><td>Cluster + Ops</td><td>10</td><td>集群管理 / 统计 / 备份</td></tr></tbody></table><h2 id="预编译库" tabindex="-1">预编译库 <a class="header-anchor" href="#预编译库" aria-label="Permalink to &quot;预编译库&quot;">​</a></h2><p><code>talon-sdk</code> 的 <code>lib/</code> 目录包含 4 个平台的预编译库，由 CI 自动构建推送：</p><table tabindex="0"><thead><tr><th>系统</th><th>架构</th><th>静态库</th><th>动态库</th></tr></thead><tbody><tr><td>macOS</td><td>arm64 (Apple Silicon)</td><td><code>.a</code> ✅</td><td><code>.dylib</code> ✅</td></tr><tr><td>macOS</td><td>amd64 (Intel)</td><td><code>.a</code> ✅</td><td><code>.dylib</code> ✅</td></tr><tr><td>Linux</td><td>amd64（海光/兆芯）</td><td><code>.a</code> ✅</td><td><code>.so</code> ✅</td></tr><tr><td>Linux</td><td>arm64（鲲鹏/飞腾）</td><td><code>.a</code> ✅</td><td><code>.so</code> ✅</td></tr><tr><td>Windows</td><td>amd64</td><td><code>.lib</code> ✅</td><td><code>.dll</code> ✅</td></tr><tr><td>Linux</td><td>loongarch64（龙芯）</td><td><code>.a</code> ✅</td><td><code>.so</code> ✅</td></tr><tr><td>Linux</td><td>riscv64</td><td><code>.a</code> ✅</td><td><code>.so</code> ✅</td></tr></tbody></table><h3 id="信创平台支持" tabindex="-1">信创平台支持 <a class="header-anchor" href="#信创平台支持" aria-label="Permalink to &quot;信创平台支持&quot;">​</a></h3><table tabindex="0"><thead><tr><th>芯片</th><th>架构</th><th>目录</th></tr></thead><tbody><tr><td>鲲鹏 (Kunpeng) / 飞腾 (Phytium)</td><td>arm64</td><td><code>linux_arm64</code></td></tr><tr><td>海光 (Hygon) / 兆芯 (Zhaoxin)</td><td>x86_64</td><td><code>linux_amd64</code></td></tr><tr><td>龙芯 (Loongson)</td><td>loongarch64</td><td><code>linux_loongarch64</code></td></tr><tr><td>RISC-V</td><td>riscv64</td><td><code>linux_riscv64</code></td></tr></tbody></table><h3 id="库查找优先级" tabindex="-1">库查找优先级 <a class="header-anchor" href="#库查找优先级" aria-label="Permalink to &quot;库查找优先级&quot;">​</a></h3><ol><li><code>TALON_LIB_PATH</code> 环境变量（直接指定文件路径）</li><li><code>talon-sdk/lib/{platform}/</code> 内嵌库（自动检测平台）</li><li>系统搜索路径</li></ol><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┐  ┌──────────────┐  ┌──────────────┐</span></span>
<span class="line"><span>│   Go SDK     │  │ Python SDK   │  │ Node.js SDK  │</span></span>
<span class="line"><span>│   (cgo)      │  │  (ctypes)    │  │  (ffi-napi)  │</span></span>
<span class="line"><span>└──────┬───────┘  └──────┬───────┘  └──────┬───────┘</span></span>
<span class="line"><span>       │                 │                 │</span></span>
<span class="line"><span>       ▼                 ▼                 ▼</span></span>
<span class="line"><span>  ┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>  │          talon_execute(db, json_cmd)         │</span></span>
<span class="line"><span>  │              C ABI (FFI 层)                  │</span></span>
<span class="line"><span>  └──────────────────┬──────────────────────────┘</span></span>
<span class="line"><span>                     │</span></span>
<span class="line"><span>                     ▼</span></span>
<span class="line"><span>  ┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>  │              Talon 引擎 (Rust)               │</span></span>
<span class="line"><span>  │  SQL │ KV │ TS │ MQ │ Vec │ FTS │ Geo │ Graph │</span></span>
<span class="line"><span>  └─────────────────────────────────────────────┘</span></span></code></pre></div>`,17)])])}const u=d(o,[["render",s]]);export{b as __pageData,u as default};
